async function answerFrame(
  ws: WebSocket,
  sessionStore: SessionStore,
  history: {enabled: boolean} | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    const userId = (ws as unknown as {userId: string | number}).userId;
    if (!history?.enabled) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled for this engine');
      return;
    }

    if (!sessionStore.listFor) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'This session store does not support conversation lists');
      return;
    }

    const sessions = await sessionStore.listFor(userId, {limit: message.limit, before: message.before});
    sendSessionList(
      ws,
      sessions.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      }))
    );
  }
}

